/**
 * League Gothic (SIL Open Font License 1.1), base64-encoded.
 *
 * The share image renders the wordmark as text, so Satori needs the real font
 * bytes. Embedding them keeps the promise the route was built on: the image is
 * drawn entirely from code, with no disk read and no network call, so it also
 * works when prerendered at build time and inside a serverless bundle where a
 * path under src/ may not be traced.
 *
 * Regenerate with the font file in this directory if the typeface ever changes.
 */
export const LEAGUE_GOTHIC_BASE64 =
  "";

/** Decoded font bytes for `next/og`. */
export function leagueGothicFontData(): Buffer {
  return Buffer.from(LEAGUE_GOTHIC_BASE64, "base64");
}
